import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        HashMap<Long, Long> seen = new HashMap<>();
        long answer = 0;
        for (int i = 0; i < n; i++) {
            long x = nextLong(), y = nextLong();
            // every earlier object within distance 1 on both axes sits on one of 9 cells
            for (long dx = -1; dx <= 1; dx++)
                for (long dy = -1; dy <= 1; dy++) answer += seen.getOrDefault((x + dx) * 100000 + (y + dy), 0L);
            seen.merge(x * 100000 + y, 1L, Long::sum);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	seen := map[[2]int]int{}
	answer := 0
	for i := 0; i < n; i++ {
		var x, y int
		fmt.Fscan(in, &x, &y)
		// every earlier object within distance 1 on both axes sits on one of 9 cells
		for dx := -1; dx <= 1; dx++ {
			for dy := -1; dy <= 1; dy++ {
				answer += seen[[2]int{x + dx, y + dy}]
			}
		}
		seen[[2]int{x, y}]++
	}
	fmt.Println(answer)
}
